package org.brightstats.desktop;
import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.chart.*;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import org.brightstats.stats.AdjustedCopula;
final class AdjustedCopulaPlots {
    private AdjustedCopulaPlots(){}
    static void add(TabPane tabs,AdjustedCopula.Fit fit){var equation=fit.equations().stream().filter(e->e.correction()!=null).findFirst().orElseThrow();double[] predictions=equation.predictions(),residuals=equation.residuals(),sorted=residuals.clone();Arrays.sort(sorted);int count=Math.min(1000,predictions.length);NumberAxis x=new NumberAxis(),y=new NumberAxis();x.setLabel("Augmented fitted "+fit.model().names().get(equation.target()));y.setLabel("Augmented residual");x.setForceZeroInRange(false);y.setForceZeroInRange(false);ScatterChart<Number,Number> scatter=new ScatterChart<>(x,y);scatter.setTitle("Adjusted-system residuals: "+fit.model().names().get(equation.target()));scatter.setAnimated(false);scatter.setMinHeight(430);var points=new XYChart.Series<Number,Number>();points.setName("Analysis rows");NumberAxis qx=new NumberAxis(),qy=new NumberAxis();qx.setLabel("Standard normal quantile");qy.setLabel("Ordered augmented residual");qx.setForceZeroInRange(false);qy.setForceZeroInRange(false);LineChart<Number,Number> qq=new LineChart<>(qx,qy);qq.setTitle("Adjusted-system augmented residual Q–Q");qq.setCreateSymbols(false);qq.setAnimated(false);qq.setMinHeight(430);var quantiles=new XYChart.Series<Number,Number>();quantiles.setName("Empirical residual quantiles");var normal=new org.apache.commons.math3.distribution.NormalDistribution();for(int i=0;i<count;i++){int row=(int)Math.round(i*(predictions.length-1.0)/(count-1));points.getData().add(new XYChart.Data<>(predictions[row],residuals[row]));quantiles.getData().add(new XYChart.Data<>(normal.inverseCumulativeProbability((row+.5)/sorted.length),sorted[row]));}scatter.getData().add(points);qq.getData().add(quantiles);Label note=UiAppearance.label("Descriptive diagnostics for the first corrected equation. Augmented residuals do not reveal the unobserved structural error or establish copula identification. At most 1,000 evenly spaced source rows/ordered residuals are displayed; complete arrays remain in numeric results.");note.setWrapText(true);VBox content=new VBox(12,note,scatter,qq);content.setPadding(new Insets(12));ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);Tab tab=new Tab("Adjusted copula plots",scroll);tab.setClosable(false);tabs.getTabs().add(tab);}
}
